    [2006902243] = {
        ["english"] = { [1] = "This land belongs to the Dark Iron Dwarves.  Prepare to see the afterlife, <class>!" },
        ["text"] = "Ця земля належить дворфам Темного Заліза. Готуйся до смерті, {клас:к}!#afterlife, <class>!",
