        ["priority"] = 1,
    },
    [2015546310] = {
        ["english"] = { [1] = "Step right up and wet your whistle." },
        ["text"] = "Підходьте і візьміть щось випити.",
        ["npcs"] = { [1] = "Barkeep Hann" },
        ["priority"] = 1,
    },
    [2916633754] = {
        ["english"] = { [1] = "Psssst.  We just got some Moonshine in. . . ." },
