                ["priority"] = 1,
            },
        },
    },
    [1153774846] = {
        ["english"] = { [1] = "Tell the Warden this prison is ours now!" },
        ["text"] = "Скажіть наглядачу, що ця в'язниця тепер наша!",
        ["npcs"] = { [1] = "Bazil Thredd" },
        ["priority"] = 1,
