                ["npcs"] = { [1] = "Bruegal Ironknuckle" },
                ["priority"] = 1,
            },
        },
    },
    [1312180711] = {
        ["english"] = { [1] = "Outsiders! Kill em all!" },
        ["text"] = "Чужинці! Вбийте їх всіх!",
        ["npcs"] = { [1] = "Bazil Thredd" },
        ["priority"] = 1,
        ["alternatives"] = {
            [1] = {
