                ["npcs"] = { [1] = "Bruegal Ironknuckle" },
                ["priority"] = 1,
            },
        },
    },
    [1926378372] = {
        ["english"] = { [1] = "I'll crush your skull beneath my boot!" },
        ["text"] = "Я розчавлю твій череп своїм чоботом!",
        ["npcs"] = { [1] = "Bazil Thredd" },
        ["priority"] = 1,
        ["alternatives"] = {
            [1] = {
                ["english"] = { [1] = "I'll crush your skull beneath my boot!" },
