                ["priority"] = 1,
            },
        },
    },
    [272845343] = {
        ["english"] = { [1] = "It'll be quick, but it won't be painless!" },
        ["text"] = "Це буде швидко, але не безболісно!",
        ["npcs"] = { [1] = "Bazil Thredd" },
        ["priority"] = 1,
        ["alternatives"] = {
            [1] = {
