                ["npcs"] = { [1] = "Bruegal Ironknuckle" },
                ["priority"] = 1,
            },
        },
    },
    [4061880385] = {
        ["english"] = { [1] = "Death to the Warden's men!" },
        ["text"] = "Смерть людям наглядача!",
        ["npcs"] = { [1] = "Bazil Thredd" },
        ["priority"] = 1,
        ["alternatives"] = {
            [1] = {
