    [4157528091] = {
        ["english"] = { [1] = "Fresh meat!" },
        ["text"] = "Свіже м'ясо!",
        ["npcs"] = { [1] = "Bazil Thredd" },
        ["priority"] = 1,
        ["alternatives"] = {
            [1] = {
                ["english"] = { [1] = "Fresh meat!" },
                ["text"] = "Свіже м'ясо!",
