        ["text"] = "За Темне Пасмо!",
        ["npcs"] = { [1] = "Dark Strand Assassin" },
        ["priority"] = 1,
    },
    [3631428161] = {
        ["english"] = { [1] = "The Wickerman Festival now begins!  Power to the Forsaken!" },
        ["text"] = "Фестиваль Плетеного чоловічка починається! Силу відреченим!",
        ["npcs"] = { [1] = "Darkcaller Yanka" },
        ["priority"] = 1,
    },
    [3476960721] = {
