        ["text"] = "Претендента переможено!",
        ["npcs"] = { [1] = "Twiggy Flathead" },
        ["priority"] = 1,
    },
    [680847002] = {
        ["english"] = { [1] = "%s senses your presence and opens a nether portal!" },
