        ["text"] = "Я вшиваюсь звідси!",
        ["npcs"] = { [1] = "Weegli Blastfuse" },
        ["priority"] = 1,
    },
    [944656130] = {
        ["english"] = { [1] = "The fortune is mine, Alexi! Your end comes soon!" },
