        ["npcs"] = { [1] = "William" },
        ["priority"] = 1,
    },
    [2464402816] = {
        ["english"] = { [1] = "I have your dolly! Nyah nyah!" },
        ["text"] = "У мене твоя лялька! Бе-бе-бе!",
        ["npcs"] = { [1] = "William" },
        ["priority"] = 1,
    },
    [2471581622] = {
