        ["npcs"] = { [1] = "William" },
        ["priority"] = 1,
    },
    [2603669844] = {
        ["english"] = { [1] = "How dare you enter my sanctum!" },
        ["text"] = "Як ви смієте входити в мій храм!",
        ["npcs"] = { [1] = "Witch Doctor Zum'rah" },
        ["priority"] = 1,
    },
    [3562114341] = {
        ["english"] = { [1] = "Sands consume you!" },
