        ["npcs"] = { [1] = "Witch Doctor Zum'rah" },
        ["priority"] = 1,
    },
    [4267058799] = {
        ["english"] = { [1] = "Come to me, my children!" },
        ["text"] = "Ходіть до мене, діти мої!",
        ["npcs"] = { [1] = "Witch Doctor Zum'rah" },
        ["priority"] = 1,
