        ["text"] = "Помри!",
        ["npcs"] = { [1] = "Witch Doctor Zum'rah" },
        ["priority"] = 1,
    },
    [2632300111] = {
        ["english"] = { [1] = "I can't believe it! You've destroyed my pack... Now face my wrath!" },
        ["text"] = "Не можу в це повірити! Ви знищили мою зграю... Тепер ви відчуєте мій гнів!",
        ["npcs"] = { [1] = "Wolf Master Nandos" },
        ["priority"] = 1,
    },
    [1741994312] = {
